  if (utils.isFunction(headers.get)) {
    const value = headers.get(name);
    if (value == null) {
      return '';
    }
    return value;
  }
  const key = findKey(headers, name);
  if (key) {
    return headers[key];
  }
  if (headers[name] == null) {
    return '';
  }
  return headers[name];
}

function findKey(obj, key) {
  key = key.toLowerCase();
  const keys = Object.keys(obj);
  let i = keys.length;
  let _key;
  while (i-- > 0) {
    _key = keys[i];
    if (key === _key.toLowerCase()) {
